1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tidy Nest - Choose your slot</title>
7	<style>
8	  body { font-family: system-ui, -apple-system, sans-serif; color: #171717;
9	         background: #fdfcf9; margin: 0; padding: 32px 16px; }
10	  .wrap { max-width: 620px; margin: 0 auto; }
11	  .card { background: #fff; border: 1px solid #e6e3dc; border-radius: 14px; padding: 28px; }
12	  h1 { font-size: 22px; margin: 0 0 4px; }
13	  .sub { color: #656565; font-size: 14px; margin: 0 0 24px; }
14	
15	  .steps { display: flex; gap: 8px; margin-bottom: 26px; }
16	  .step { flex: 1; height: 4px; background: #e6e3dc; border-radius: 2px; }
17	  .step.on { background: #171717; }
18	  .steplabel { font-size: 13px; color: #656565; margin-bottom: 20px; }
19	
20	  .field { margin-bottom: 20px; }
21	  .flabel { display: block; font-size: 14px; font-weight: 600; margin-bottom: 7px; }
22	
23	  .select { border: 1px solid #d6d2c8; border-radius: 8px; padding: 11px 12px;
24	            font-size: 15px; cursor: pointer; background: #fff; position: relative; }
25	  .select:after { content: "\25BC"; float: right; font-size: 10px; color: #656565; }
26	  .options { display: none; border: 1px solid #d6d2c8; border-top: none;
27	             border-radius: 0 0 8px 8px; }
28	  .options.open { display: block; }
29	  .opt { padding: 10px 12px; font-size: 15px; cursor: pointer; }
30	  .opt:hover { background: #f5f3ee; }
31	
32	  .slotgrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
33	  .slot { border: 1px solid #d6d2c8; border-radius: 8px; padding: 12px;
34	          text-align: center; font-size: 15px; cursor: pointer; }
35	  .slot.taken { color: #b5b1a8; background: #faf9f6; cursor: not-allowed; }
36	
37	  .summary { border-top: 1px solid #e6e3dc; margin-top: 24px; padding-top: 16px; }
38	  .line { display: flex; justify-content: space-between; font-size: 15px; margin-bottom: 8px; }
39	  .line.total { font-weight: 700; font-size: 17px; }
40	  .addon { display: flex; justify-content: space-between; align-items: center;
41	           padding: 10px 0; font-size: 15px; }
42	  .toggle { border: 1px solid #171717; border-radius: 999px; padding: 5px 14px;
43	            font-size: 13px; cursor: pointer; }
44	
45	  .cta { background: #171717; color: #fff; border: none; width: 100%; padding: 14px;
46	         border-radius: 10px; font-weight: 600; font-size: 15px; cursor: pointer;
47	         margin-top: 20px; font-family: inherit; }
48	
49	  .backdrop { display: none; position: fixed; inset: 0; background: rgba(0,0,0,.45); }
50	  .backdrop.open { display: block; }
51	  .modal { background: #fff; max-width: 420px; margin: 12vh auto; border-radius: 14px;
52	           padding: 24px; }
53	  .modal h2 { font-size: 18px; margin: 0 0 4px; }
54	  .modal p { color: #656565; font-size: 14px; margin: 0 0 18px; }
55	  .x { float: right; font-size: 20px; color: #656565; cursor: pointer; line-height: 1; }
56	</style>
57	</head>
58	<body>
59	<div class="wrap">
60	  <div class="card">
61	
62	    <div class="steps">
63	      <div class="step on"></div>
64	      <div class="step"></div>
65	      <div class="step"></div>
66	    </div>
67	    <p class="steplabel" id="steplabel">Step 1 of 3 &mdash; Choose your clean</p>
68	
69	    <h1>Choose your slot</h1>
70	    <p class="sub">Two-bedroom flat &middot; Tuesday 14 September</p>
71	
72	    <div class="field">
73	      <span class="flabel">Type of clean</span>
74	      <div class="select" onclick="toggleOptions()">Standard clean</div>
75	      <div class="options" id="options">
76	        <div class="opt" onclick="pick('Standard clean', 89)">Standard clean &mdash; &pound;89</div>
77	        <div class="opt" onclick="pick('Deep clean', 149)">Deep clean &mdash; &pound;149</div>
78	        <div class="opt" onclick="pick('End of tenancy', 240)">End of tenancy &mdash; &pound;240</div>
79	      </div>
80	    </div>
81	
82	    <div class="field">
83	      <span class="flabel">Arrival time</span>
84	      <div class="slotgrid">
85	        <div class="slot" onclick="openModal('8:00am')">8:00am</div>
86	        <div class="slot taken">10:00am</div>
87	        <div class="slot" onclick="openModal('12:00pm')">12:00pm</div>
88	        <div class="slot" onclick="openModal('2:00pm')">2:00pm</div>
89	        <div class="slot" onclick="openModal('4:00pm')">4:00pm</div>
90	        <div class="slot taken">6:00pm</div>
91	      </div>
92	    </div>
93	
94	    <div class="addon">
95	      <span>Add oven cleaning (+&pound;35)</span>
96	      <div class="toggle" onclick="toggleAddon(this)">Add</div>
97	    </div>
98	
99	    <div class="summary">
100	      <div class="line"><span id="planname">Standard clean</span><span id="planprice">&pound;89.00</span></div>
101	      <div class="line" id="addonline" style="display:none"><span>Oven cleaning</span><span>&pound;35.00</span></div>
102	      <div class="line total"><span>Total</span><span id="total">&pound;89.00</span></div>
103	    </div>
104	
105	    <button class="cta" onclick="next()">Continue to payment</button>
106	  </div>
107	</div>
108	
109	<div class="backdrop" id="backdrop">
110	  <div class="modal">
111	    <span class="x" onclick="closeModal()">&times;</span>
112	    <h2>Confirm your arrival window</h2>
113	    <p id="modaltext">The cleaner will arrive between 8:00am and 9:00am.</p>
114	    <button class="cta" onclick="closeModal()">That works</button>
115	  </div>
116	</div>
117	
118	<script>
119	var price = 89, addon = 0;
120	
121	function toggleOptions() {
122	  document.getElementById('options').classList.toggle('open');
123	}
124	function pick(name, p) {
125	  price = p;
126	  document.getElementById('planname').textContent = name;
127	  document.getElementById('planprice').textContent = '£' + p.toFixed(2);
128	  document.querySelector('.select').firstChild.nodeValue = name;
129	  document.getElementById('options').classList.remove('open');
130	  render();
131	}
132	function toggleAddon(el) {
133	  addon = addon ? 0 : 35;
134	  el.textContent = addon ? 'Remove' : 'Add';
135	  document.getElementById('addonline').style.display = addon ? 'flex' : 'none';
136	  render();
137	}
138	function render() {
139	  document.getElementById('total').textContent = '£' + (price + addon).toFixed(2);
140	}
141	function openModal(time) {
142	  document.getElementById('modaltext').textContent =
143	    'The cleaner will arrive between ' + time + ' and one hour later.';
144	  document.getElementById('backdrop').classList.add('open');
145	}
146	function closeModal() {
147	  document.getElementById('backdrop').classList.remove('open');
148	}
149	function next() {
150	  document.querySelectorAll('.step')[1].classList.add('on');
151	  document.getElementById('steplabel').textContent = 'Step 2 of 3 — Your details';
152	}
153	</script>
154	</body>
155	</html>
