61	<body>
62	<div class="wrap">
63	  <div class="card">
64	
65	    <div class="steps">
66	      <div class="step on"></div>
67	      <div class="step"></div>
68	      <div class="step"></div>
69	    </div>
70	    <p class="steplabel" id="steplabel">Step 1 of 3 &mdash; Choose your clean</p>
