72	    <h1>Choose your slot</h1>
73	    <p class="sub">Two-bedroom flat &middot; Tuesday 14 September</p>
74	
75	    <div class="field">
76	      <label class="flabel" for="cleanType">Type of clean</label>
77	      <div class="selectwrap">
78	        <select class="select" id="cleanType" onchange="pick()">
79	          <option value="89" data-name="Standard clean">Standard clean &mdash; &pound;89</option>
80	          <option value="149" data-name="Deep clean">Deep clean &mdash; &pound;149</option>
81	          <option value="240" data-name="End of tenancy">End of tenancy &mdash; &pound;240</option>
82	        </select>
83	        <span class="selectarrow" aria-hidden="true">&#9660;</span>
84	      </div>
85	    </div>
86	
87	    <div class="field">
88	      <span class="flabel" id="slotlabel">Arrival time</span>
89	      <div class="slotgrid" role="group" aria-labelledby="slotlabel">
90	        <button type="button" class="slot" aria-pressed="false" onclick="selectSlot(this,'8:00am')">8:00am</button>
91	        <button type="button" class="slot taken" disabled aria-label="10:00am, unavailable">10:00am</button>
92	        <button type="button" class="slot" aria-pressed="false" onclick="selectSlot(this,'12:00pm')">12:00pm</button>
93	        <button type="button" class="slot" aria-pressed="false" onclick="selectSlot(this,'2:00pm')">2:00pm</button>
94	        <button type="button" class="slot" aria-pressed="false" onclick="selectSlot(this,'4:00pm')">4:00pm</button>
95	        <button type="button" class="slot taken" disabled aria-label="6:00pm, unavailable">6:00pm</button>
96	      </div>
97	    </div>
98	
99	    <div class="addon">
100	      <span id="addonlabel">Add oven cleaning (+&pound;35)</span>
101	      <button type="button" class="toggle" aria-pressed="false" aria-labelledby="addonlabel" onclick="toggleAddon(this)">Add</button>
102	    </div>
103	
104	    <div class="summary" aria-live="polite" aria-atomic="true">
105	      <div class="line"><span id="planname">Standard clean</span><span id="planprice">&pound;89.00</span></div>
106	      <div class="line" id="addonline" style="display:none"><span>Oven cleaning</span><span>&pound;35.00</span></div>
