116	    <button type="button" class="x" id="modalClose" aria-label="Close dialog" onclick="closeModal()">&times;</button>
117	    <h2 id="modalTitle">Confirm your arrival window</h2>
118	    <p id="modaltext">The cleaner will arrive between 8:00am and 9:00am.</p>
119	    <button class="cta" onclick="closeModal()">That works</button>
120	  </div>
121	</div>
122	
123	<script>
124	var price = 89, addon = 0, pendingTrigger = null;
125	
126	function pick() {
127	  var sel = document.getElementById('cleanType');
128	  var opt = sel.options[sel.selectedIndex];
129	  price = Number(sel.value);
130	  document.getElementById('planname').textContent = opt.dataset.name;
131	  document.getElementById('planprice').textContent = '£' + price.toFixed(2);
132	  render();
133	}
134	function selectSlot(el, time) {
135	  document.querySelectorAll('.slot').forEach(function (s) {
136	    s.classList.remove('selected');
137	    if (!s.disabled) s.setAttribute('aria-pressed', 'false');
138	  });
139	  el.classList.add('selected');
140	  el.setAttribute('aria-pressed', 'true');
141	  openModal(time, el);
142	}
143	function toggleAddon(el) {
144	  addon = addon ? 0 : 35;
145	  el.textContent = addon ? 'Remove' : 'Add';
146	  el.setAttribute('aria-pressed', addon ? 'true' : 'false');
147	  document.getElementById('addonline').style.display = addon ? 'flex' : 'none';
148	  render();
149	}
150	function render() {
151	  document.getElementById('total').textContent = '£' + (price + addon).toFixed(2);
152	}
153	function openModal(time, trigger) {
154	  pendingTrigger = trigger || pendingTrigger;
155	  document.getElementById('modaltext').textContent =
156	    'The cleaner will arrive between ' + time + ' and one hour later.';
157	  document.getElementById('backdrop').classList.add('open');
158	  document.addEventListener('keydown', onModalKeydown);
159	  document.getElementById('modalDialog').focus();
160	}
161	function closeModal() {
162	  document.getElementById('backdrop').classList.remove('open');
163	  document.removeEventListener('keydown', onModalKeydown);
164	  if (pendingTrigger) { pendingTrigger.focus(); }
165	}
166	function onModalKeydown(e) {
167	  if (e.key === 'Escape') {
168	    closeModal();
169	    return;
170	  }
171	  if (e.key === 'Tab') {
172	    var focusables = document.querySelectorAll(
173	      '#backdrop button, #backdrop [href], #backdrop input, #backdrop select, #backdrop textarea, #backdrop [tabindex]:not([tabindex="-1"])'
174	    );
175	    if (!focusables.length) return;
176	    var first = focusables[0], last = focusables[focusables.length - 1];
177	    if (e.shiftKey && document.activeElement === first) {
178	      e.preventDefault();
179	      last.focus();
180	    } else if (!e.shiftKey && document.activeElement === last) {
181	      e.preventDefault();
182	      first.focus();
183	    }
184	  }
185	}
186	function next() {
187	  document.querySelectorAll('.step')[1].classList.add('on');
188	  document.getElementById('steplabel').textContent = 'Step 2 of 3 — Your details';
189	}
190	</script>
191	</body>
